def compute_area(path, initial_height=0):
    h = initial_height
    total = 0
    for step in path:
        if step == 'E':
            total += h
        elif step == 'N':
            h += 1
    return total

from functools import lru_cache

@lru_cache(maxsize=None)
def q_binomial(m, n):
    if m == 0 or n == 0:
        return {0: 1}
    p1 = q_binomial(m - 1, n)
    p2 = q_binomial(m, n - 1)
    result = dict(p1)
    for k, v in p2.items():
        result[k + m] = result.get(k + m, 0) + v
    return result

def is_valid_path(path, forbidden):
    x, y = 0, 0
    if (x, y) in forbidden:
        return False
    for step in path:
        if step == 'E': x += 1
        else: y += 1
        if (x, y) in forbidden:
            return False
    return True
